// next.config.ts
import type { NextConfig } from "next"

const nextConfig: NextConfig = {
  images: {
    remotePatterns: [
      new URL("https://cdn.oshxona.uz/rasmlar/**"),
      {
        protocol: "https",
        hostname: "**.oshxona.uz",   // har qanday subdomen
        pathname: "/media/**",
        search: "",                  // so'rov parametrlari bo'lmasin
      },
    ],
    localPatterns: [{ pathname: "/g/**" }],
  },
}

export default nextConfig

import { getImageProps } from "next/image"

export default function Hero() {
  const common = { alt: "Menyu banneri", sizes: "100vw" }
  const { props: { srcSet: wide } } =
    getImageProps({ ...common, src: "/wide.jpg", width: 1600, height: 600 })
  const { props: { srcSet: tall, ...rest } } =
    getImageProps({ ...common, src: "/tall.jpg", width: 600, height: 900 })

  return (
    <picture>
      <source media="(min-width: 768px)" srcSet={wide} />
      <source srcSet={tall} />
      <img {...rest} style={{ width: "100%", height: "auto" }} />
    </picture>
  )
}

