// fayl: app/page.tsx
import { getImageProps } from "next/image"

function getBackgroundImage(srcSet = "") {
  const imageSet = srcSet
    .split(", ")
    .map((str) => {
      const [url, dpi] = str.split(" ")
      return `url("${url}") ${dpi}`
    })
    .join(", ")
  return `image-set(${imageSet})`
}

export default function Home() {
  const {
    props: { srcSet },
  } = getImageProps({ alt: "", width: 128, height: 128, src: "/chef.jpg" })
  const style = { height: 240, backgroundImage: getBackgroundImage(srcSet) }

  return (
    <main style={style}>
      <h1>Oshpazlik maktabi</h1>
    </main>
  )
}

