export default function Page() {
  const [show, setShow] = useState(true)
  const [events, setEvents] = useState<string[]>([])
  const log = (event: string) => setEvents((prev) => [...prev, event])

  useEffect(() => {
    const hide = setTimeout(() => setShow(false), 1500)
    const again = setTimeout(() => setShow(true), 2500)
    return () => {
      clearTimeout(hide)
      clearTimeout(again)
    }
  }, [])

  return (
    <main>
      {show && <MapBox log={log} />}
      <p>Hodisalar: {events.join(", ")}</p>
    </main>
  )
}

