"use client"

import { sendGAEvent } from "@next/third-parties/google"
import { useEffect, useRef, useState } from "react"

export function BuyButton() {
  const button = useRef<HTMLButtonElement>(null)
  const [sent, setSent] = useState("hali yuborilmadi")

  function handleClick() {
    sendGAEvent("event", "buttonClicked", { value: "osh" })
    // dataLayer'dagi oxirgi yozuv (Arguments obyekti) qiymatlari
    setSent(JSON.stringify(Object.values(window.dataLayer?.at(-1) ?? {})))
  }

  // sinov uchun: 2,5 soniyadan keyin tugma o'zi "bosiladi"
  useEffect(() => {
    const timer = setTimeout(() => button.current?.click(), 2500)
    return () => clearTimeout(timer)
  }, [])

  return (
    <>
      <button ref={button} onClick={handleClick}>
        Sotib olish
      </button>
      <p>dataLayer: {sent}</p>
    </>
  )
}

