// fayl: scripts/top-modules.mjs
import { readFileSync } from 'node:fs'

const lines = readFileSync('graph.jsonl', 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l))
const totals = new Map()

for (const row of lines) {
    if (row.type !== 'part' || row.route !== '/reports') continue
    if (!row.filename.includes('/static/chunks/')) continue          // faqat client chunk'lar
    const m = /node_modules\/((?:@[^/]+\/)?[^/]+)/.exec(row.source_path)
    const name = m ? m[1] : '(loyiha kodi)'
    totals.set(name, (totals.get(name) ?? 0) + row.compressed_size)
}

const top = [...totals].sort((a, b) => b[1] - a[1]).slice(0, 4)
for (const [name, size] of top) {
    console.log(name.padEnd(14), (size / 1024).toFixed(1) + ' kB (gzip)')
}

