// fayl: app/product/sitemap.ts
import type { MetadataRoute } from 'next'

const LIMIT = 50000

async function countProducts() {
    return 120000                                    // haqiqiy loyihada: await db.product.count()
}

export async function generateSitemaps() {
    const total = await countProducts()
    const pages = Math.ceil(total / LIMIT)           // 120000 / 50000 -> 3
    return Array.from({ length: pages }, (_, id) => ({ id }))
}

export default async function sitemap(props: {
    id: Promise<string>
}): Promise<MetadataRoute.Sitemap> {
    const id = Number(await props.id)
    const first = id * LIMIT + 1
    return [
        { url: `https://oshxona.uz/product/${first}` },
        { url: `https://oshxona.uz/product/${Math.min(first + LIMIT - 1, 120000)}` },
    ]
}

