    { path: '/manifest.webmanifest', type: 'application/manifest+json', must: '"name"' },
]

let failed = false
for (const { path, type, must } of checks) {
    const res = await fetch(base + path)
    const body = await res.text()
    const ok = res.status === 200 && (res.headers.get('content-type') ?? '').startsWith(type) && body.includes(must)
    console.log((ok ? 'OK   ' : 'XATO ') + path + ' (' + res.status + ')')
    if (!ok) failed = true
}
process.exitCode = failed ? 1 : 0

