const NAMES = ['TTFB', 'FCP', 'LCP', 'INP', 'CLS']

export async function POST(request: Request) {
    let data: unknown
    try {
        data = await request.json()
    } catch {
        return Response.json({ error: "JSON noto'g'ri" }, { status: 400 })
    }

    const { name, value } = (data ?? {}) as { name?: string; value?: unknown }
    if (!name || !NAMES.includes(name) || typeof value !== 'number') {
        return Response.json({ error: "name yoki value noto'g'ri" }, { status: 400 })
