// fayl: app/_components/analytics.tsx
'use client'

import { useReportWebVitals } from 'next/web-vitals'

type Metric = Parameters<Parameters<typeof useReportWebVitals>[0]>[0]

const RATE = Number(process.env.NEXT_PUBLIC_SAMPLE_RATE ?? 0.1)

function hash(text: string) {
    let h = 0
    for (const ch of text) h = (h * 31 + ch.charCodeAt(0)) >>> 0
    return h
}

function report(metric: Metric) {
    if (!document.cookie.includes('analytics=1')) return        // rozilik yo'q
    if ((hash(metric.id) % 100) / 100 >= RATE) return           // tanlab olinmadi

    navigator.sendBeacon('/api/vitals', JSON.stringify({
        name: metric.name,
        value: Math.round(metric.name === 'CLS' ? metric.value * 1000 : metric.value),
        rating: metric.rating,
        path: location.pathname,
    }))
}

export function AnalyticsProvider() {
    useReportWebVitals(report)
    return null
}

